import { owners, manualSteps, dependencies, numbers, money, artifact, approved, canApprove, allApproved } from './proposal-model.mjs';
export const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const e = escapeHtml;
const icon = (file, label = '') => `<img src="assets/${e(file)}" alt="${e(label)}">`;
const badge = (text, kind = '') => `<span class="badge ${kind}">${text}</span>`;
const person = owner => `<span class="initial">${owner.name[0]}</span><span><b>${owner.name}</b><small>${owner.department}</small></span>`;
const tools = owner => `<div class="tool-pair"><span>${icon(owner.icon)}${owner.ai}</span><span>${icon(owner.systemIcon)}${owner.system}</span></div>`;
export const scenes = [
  { eyebrow: 'Scene 1 · The individual productivity win', title: 'Five AI Tools. One Unfinished Proposal.', lead: 'Five people finish their contributions faster. Leah still has to turn them into one approved customer proposal.', cue: 'Everyone finished their AI work. So why isn’t the proposal finished?' },
  { eyebrow: 'Scene 2 · A legitimate new requirement', title: 'Then the client adds one location.', lead: 'The five original outputs were correct. This new request changes the shared assumptions after those outputs are complete.', cue: 'Nobody made a mistake. The client changed the requirement.' },
  { eyebrow: 'Scene 3 · The work between the work', title: 'Leah becomes the connection between systems.', lead: 'People can use AI again. Leah still collects the results, carries assumptions between teams, resolves dependencies and chases approvals.', cue: 'AI finished five tasks. Leah is still doing the sixth: connecting them.' },
  { eyebrow: 'Scene 4 · What Nine-67 would build', title: 'Connect the work, information and decisions.', lead: 'One shared requirement drives the affected reviews. People own decisions; the workflow carries their approved results forward.', cue: 'This is coordination across the tools they already have.' },
  { eyebrow: 'Scene 5 · Request into completed work', title: 'Five contributions. One customer-ready proposal.', lead: 'Readiness means the documents agree, the decisions are approved, and the required system updates are verified.', cue: 'Individual productivity becomes a completed company outcome.' }
];
const chats = {
  sales: ['Turn Rachel’s Austin brief into a structured opportunity summary and draft our internal handoff.', 'The brief covers one Austin location, a 90-day improvement project and a $750,000 opportunity. I’ve organized the needs, deliverables and open questions for the team.', 'What can I mark complete, and what do I still need from the others?', 'Your scope brief is ready for review. Delivery must confirm staffing, finance must approve pricing, legal must approve terms, and marketing must assemble the proposal. A completed brief is not a send-ready proposal.', 'Draft the Teams message with that distinction.', '“Austin scope brief is complete. Please review your sections against this requirement. I’ll collect the approved staffing, price and terms before we release the final proposal.”'],
  delivery: ['Use our Austin scope and resource plan to prepare the 90-day delivery contribution.', 'The sample plan uses 300 consultant-days across diagnostic, design and implementation. The phases cover days 1–20, 21–50 and 51–90. Please verify the named resource allocation before signing off.', 'I reviewed the allocation. Prepare my Kantata update and a concise reply to Leah.', 'Prepared: Austin, 90 days, 300 consultant-days. Reply: “Delivery review is complete for the Austin scope. Staffing and phases are in the plan. Finance should use this approved effort basis.”', 'Does that make the whole proposal ready?', 'No. This is your delivery contribution. Pricing, terms, narrative and final approval remain separate steps. Send Leah the effort basis with the version you approved.'],
  finance: ['Use Sam’s approved 300-day Austin plan to prepare the pricing model.', 'At the sample loaded cost of $1,500 per consultant-day, delivery cost is $450,000. A $750,000 fee gives a 40.0% gross margin: ($750,000 − $450,000) ÷ $750,000.', 'I checked the assumptions. Draft my reply with the scope this price covers.', '“Finance review complete: $750,000 fee, $450,000 delivery cost, 40.0% margin. This model covers the approved 300-day Austin scope. Changes to staffing or locations require a refreshed model.”', 'What should Maya carry into the summary?', 'Use the approved fee and scope together. Do not detach the $750,000 figure from the Austin-only effort and assumptions.'],
  legal: ['Review our standard terms against the approved Austin scope, 90 days and $750,000 fee.', 'The draft identifies Austin as the covered location, the 90-day duration and the fee. Client-access dependencies and written change control are included. Review these terms before approval.', 'I’ve reviewed them. Draft a reply saying exactly what I approved.', '“Terms reviewed for Austin, 90 days and $750,000. The terms are ready for assembly against that scope. If the location, fee or timing changes, route the affected terms back to me.”', 'Can marketing edit the commercial terms while assembling?', 'Marketing can assemble approved language. Material changes to the commitments should return to the responsible approvers.'],
  marketing: ['Draft the executive summary using the four approved local contributions for Austin.', 'Draft ready: a 90-day operational improvement project at Austin with a $750,000 fee, aligned to the supplied scope, staffing, pricing and terms.', 'Prepare the SharePoint file and tell Leah what is done.', '“Executive summary complete for the Austin version. The draft references the supplied approved sections. Leah still needs to verify the assembled packet and obtain final leadership approval.”', 'What should I do if one of the source documents changes?', 'Refresh the affected narrative from the new approved source. Keep the previous version and wait for the corresponding decisions before marking the final packet ready.']
};
function aiConversation(owner) {
  return `<section class="ai-window ${owner.ai.toLowerCase()}"><header>${icon(owner.icon)}<b>${owner.ai}</b><span>${owner.name}<small>${owner.department}</small></span></header><div class="context-label">Private workspace · Original Austin requirement · Illustrative conversation</div><div class="chat-turns">${chats[owner.id].map((text,i)=>`<div class="chat-turn ${i%2?'assistant':'user'}"><small>${i%2?owner.ai:owner.name}</small><p>${e(text)}</p></div>`).join('')}</div><div class="handoff-highlight"><small>WHAT TRAVELS WITH THIS OUTPUT</small><p><mark>${owner.deliverable} complete for Austin.</mark> Share the scope, assumptions and approved version with Leah. The final proposal still requires coordination.</p></div><div class="fake-composer" aria-hidden="true">Message ${owner.ai}<span>＋ &nbsp; ↑</span></div></section>`;
}
function documentPreview(state, id, original=false) {
  const owner = owners.find(row=>row.id===id);
  const content = artifact(state,id,original);
  return `<section class="document-preview"><div class="document-toolbar">${icon(owner.systemIcon)}<b>${owner.file}</b>${badge(original?'Original · v1':`Draft · v${state.revision}`)}</div><div class="document-paper"><p class="document-label">SUMMIT ADVISORY GROUP · SAMPLE ${owner.format.toUpperCase()} PREVIEW</p><h3>${content[0]}</h3><p class="document-meta">${e(content[1])}</p><p>${e(content[2])}</p><p>${e(content[3])}</p><div class="document-owner">${person(owner)}</div></div><p class="preview-note">Structured sample content, not a live file import. Original formats are represented for the demo.</p></section>`;
}
function sceneOne(state) {
  const owner=owners.find(row=>row.id===state.selectedOwner);
  return `<div class="scoreboard"><div><small>AI-generated contributions</small><strong>5 / 5 complete <i>✓</i></strong></div><div><small>Proposal ready to send</small><strong class="amber">Not yet</strong></div><div><small>What Leah still owns</small><strong>Assembly + approvals</strong></div></div><div class="owner-tabs" role="group" aria-label="Explore each person’s work">${owners.map(row=>`<button data-owner="${row.id}" aria-pressed="${row.id===owner.id}"><div class="person">${person(row)}</div>${tools(row)}<span class="deliverable">✓ ${row.deliverable}</span></button>`).join('')}</div><div class="section-heading"><div><p class="eyebrow">Inspect a completed contribution</p><h2>${owner.name} did their part.</h2></div>${badge('Correct for the original requirement','green')}</div><div class="inspect-grid">${aiConversation(owner)}${documentPreview(state,owner.id,true)}</div><div class="thesis"><b>Five local successes. One unfinished customer outcome.</b><p>Leah must still connect these outputs, verify common assumptions and secure approval for the assembled proposal.</p></div>`;
}
function email(sender,role,time,body){return `<article class="email-message"><header><span class="initial">${sender[0]}</span><div><b>${sender}</b><small>${role}</small></div><time>${time}</time></header><div class="email-body">${body}</div></article>`;}
function mailThread(content){return `<section class="mail-window"><div class="mail-top">${icon('ms-outlook.svg')}<b>Outlook</b><span>Leah’s inbox</span></div><div class="subject"><small>NORTHSTAR DISTRIBUTION / OPPORTUNITY NSP-204</small><h2>RE: 90-day operational improvement proposal</h2></div>${content}</section>`;}
function sceneTwo(state){return `<div class="change-timing">Monday, 10:30 AM <span>All five original contributions are already complete.</span></div>${mailThread(email('Rachel Ortiz','COO · Northstar Distribution → Leah','10:30 AM','<p>Hi Leah,</p><p>We’d like to include our <b>Denver location alongside Austin</b> in the proposal. The leadership team wants both locations covered within the same 90-day engagement.</p><p>Please show the additional staffing and cost, and update the scope and terms accordingly. We still need the proposal by Friday.</p><p>Thanks for coordinating this,<br><b>Rachel</b></p>')+email('Leah','Sales · Proposal owner → Rachel','10:38 AM','<p>Hi Rachel,</p><p>Understood. I’ll coordinate the Denver addition across delivery, finance, legal and our proposal team, then return one consistent proposal with the cost impact clearly shown.</p><p>We’ll confirm the delivery assumptions as part of that review.</p><p>Best,<br>Leah</p>')+email('Rachel Ortiz','COO · Northstar Distribution → Leah','10:42 AM','<p>Perfect, thank you. Having the complete picture in one proposal will help us make the decision.</p>'))}<div class="requirement-change"><div><small>ORIGINAL · REVISION 1</small><h3>Austin</h3><p>90 days · $750,000 baseline</p></div><span aria-hidden="true">→</span><div><small>NEW REQUEST · REVISION 2</small><h3>Austin + Denver</h3><p>90 days requested · additional cost to be reviewed</p></div></div><button class="primary" data-action="change" ${state.changed?'disabled':''}>${state.changed?'✓ Client change recorded':'Record the client change →'}</button><p class="microcopy">Demo action: records sample data only. The original documents are preserved; affected sections need a new review.</p>`;}
function requireChange(){return `<div class="empty-state"><h2>Start with the client’s new requirement.</h2><p>The original Austin work is complete. Record Rachel’s Denver request to explore its handoffs.</p><button class="primary" data-action="change">Load the sample client change →</button></div>`;}
function sceneThree(state){
 if(!state.changed)return requireChange();
 const active=manualSteps[Math.max(0,state.manualCount-1)];
 const minutes=manualSteps.slice(0,state.manualCount).reduce((sum,row)=>sum+row.minutes,0);
 return `<div class="manual-header"><div class="person">${person(owners[0])}</div>${badge('Proposal workspace · Not ready','amber')}<p>Leah has all five AI outputs. She is now carrying the change between their owners.</p></div><div class="manual-grid"><ol class="manual-list">${manualSteps.map((row,i)=>`<li class="${i<state.manualCount?'done':''}"><span>${i<state.manualCount?'✓':i+1}</span><div><h3>${row.title}</h3><p>${row.tools}</p><small>${row.minutes} min of illustrative coordination</small></div></li>`).join('')}</ol><section class="handoff-desk"><div class="desk-apps">${['ms-teams.svg','ms-word.svg','ms-excel.svg','ms-outlook.svg'].map(file=>icon(file)).join('')}</div><p class="eyebrow">${state.manualCount?'Handoff '+state.manualCount:'Leah’s next task'}</p><h2>${active.title}</h2><p>${active.detail}</p><div class="manual-evidence"><b>${state.manualCount>=3?'The assumptions now need to travel together':'The documents are individually complete'}</b><p>${state.manualCount>=3?'Austin + Denver · 330 consultant-days · $810,000 fee · 90 days · revised scope and terms':'Word plans, an Excel model, a PDF review and a summary are separate artifacts. Nobody has connected the new requirement through all five.'}</p></div><button class="primary" data-action="manual" ${state.manualCount===manualSteps.length?'disabled':''}>${state.manualCount===manualSteps.length?'Approval packet assembled; leadership pending':'Walk the next manual handoff →'}</button></section></div><div class="scoreboard"><div><small>Coordination walked through</small><strong>${state.manualCount} / 6 handoffs</strong></div><div><small>Illustrative active effort</small><strong>${minutes} minutes</strong></div><div><small>Illustrative elapsed time</small><strong>Up to 3 days</strong></div></div><p class="microcopy">Scenario assumptions, not measured ROI. The full example totals 160 active minutes plus waiting for replies and approvals. No connected-workflow time saving is claimed as a measured result.</p><div class="thesis"><b>Good AI outputs do not coordinate themselves.</b><p>Each person can finish their revision faster with AI. Leah still has to move the information, decisions and current versions between them.</p></div>`;
}
const impactText={sales:'Add Denver to the authoritative client requirements.',delivery:'Review 30 extra consultant-days and parallel staffing within the 90-day plan.',finance:'Price the new effort and recalculate cost and margin.',legal:'Update locations, fee and the corresponding contractual commitments.',marketing:'Refresh the executive summary and assemble the approved sections.',leadership:'Authorize the complete proposal, after all five owners have approved the same revision.'};
function reviewPanel(state){
 const id=state.selectedReview;
 const owner=owners.find(row=>row.id===id);
 const label=owner?owner.name+' · '+owner.department:'Leadership · Final proposal approval';
 const waiting=dependencies[id].filter(key=>!approved(state,key));
 const n=numbers(state);
 return `<section class="review-panel"><div class="section-heading"><div><p class="eyebrow">Named human decision · Simulated</p><h2>${label}</h2></div>${badge(approved(state,id)?'Approved':waiting.length?'Waiting on upstream decisions':'Ready to review',approved(state,id)?'green':'amber')}</div><p>${impactText[id]}</p>${owner?`<div class="review-ai">${icon(owner.icon)}<div><b>${owner.ai} · Draft prepared from shared evidence</b><p>“Use client requirement revision ${state.revision}, ${state.sites.length} locations, the ${n.days}-day staffing basis and the approved upstream decisions. Update my section and identify what Leah needs.”</p><mark>${id==='finance'?`Fee ${money(n.fee)} · cost ${money(n.cost)} · margin ${n.margin}%.`:`This draft covers ${e(state.sites.join(' + '))} and the 90-day plan.`} ${waiting.length?'Upstream decisions must be approved before this draft is final.':'Source requirements and upstream decisions are available for review.'}</mark></div></div><div class="revision-comparison"><div><small>ORIGINAL CONTRIBUTION</small><p>${e(artifact(state,id,true)[2])}</p></div><div><small>PROPOSED REVISION ${state.revision}</small><p>${e(artifact(state,id)[2])}</p></div></div>`:`<div class="approval-summary"><b>One consistent packet</b><p>${e(state.sites.join(' + '))} · ${n.days} consultant-days · ${money(n.fee)} fee · ${n.margin}% margin · 90 days.</p><p>Client requirements, staffing, commercial terms and narrative must all reference revision ${state.revision}.</p></div>`}<p class="evidence-line">Evidence: Rachel’s change email · requirement v${state.revision} · ${owner?owner.file:'complete proposal packet'} · approval history</p>${waiting.length?`<p class="dependency-warning">Requires: ${waiting.map(key=>owners.find(row=>row.id===key)?.department.split(' · ')[0]||key).join(', ')}.</p>`:''}<button class="primary" data-approve="${id}" ${canApprove(state,id)?'':'disabled'}>${approved(state,id)?'✓ Approved for this revision':`Approve as ${owner?owner.name:'leadership'}`}</button><p class="microcopy">This button simulates the named owner’s decision. It does not obtain a real person’s approval.</p></section>`;
}
function sceneFour(state){
 if(!state.changed)return requireChange();
 const n=numbers(state);
 return `<div class="coordinator-title"><div><p class="eyebrow">Nine-67 · Proposal coordinator</p><h2>One requirement. A connected path to completion.</h2></div>${badge('Simulated integrations')}</div><div class="requirements"><div><small>SHARED REQUIREMENT</small><b>NSP-204 · Revision ${state.revision}</b></div><div><small>LOCATIONS</small><b>${e(state.sites.join(' + '))}</b></div><div><small>DURATION / DEADLINE</small><b>90 days / Proposal Friday</b></div><div><small>COMMERCIAL CHANGE</small><b>Price the additional scope</b></div></div><div class="source-strip"><span>${icon('ms-word.svg')}Word plans</span><span>${icon('ms-excel.svg')}Excel model</span><span>▧ PDF terms</span><span>${icon('ms-sharepoint.svg')}Proposal draft</span><small>Embedded sample imports · Original files preserved</small></div><button class="primary" data-action="analyze" ${state.analyzed?'disabled':''}>${state.analyzed?'✓ Five affected contributions linked':'Trace the change across all five outputs →'}</button>${state.analyzed?`<div class="coordinator-grid"><div class="approval-list" aria-label="Affected owners and approvals">${Object.keys(dependencies).map(id=>{const owner=owners.find(row=>row.id===id);return `<button data-review="${id}" aria-pressed="${state.selectedReview===id}"><span class="approval-symbol">${approved(state,id)?'✓':canApprove(state,id)?'→':'·'}</span><span><b>${owner?owner.name+' · '+owner.department.split(' · ')[0]:'Leadership'}</b><small>${approved(state,id)?'Approved · v'+state.revision:canApprove(state,id)?'Ready for review':'Waiting on upstream approval'}</small></span></button>`;}).join('')}</div>${reviewPanel(state)}</div>`:`<div class="empty-state compact"><p>The original staffing, pricing and terms remain correct for Austin. Trace the new requirement to prepare the affected revisions and assign the decisions.</p></div>`}<section class="release-panel"><div><p class="eyebrow">Coordinated updates</p><h2>${state.ready?'All required updates verified.':'Approval is followed by verification.'}</h2><p>After owner and leadership approval, simulate saving the proposal in SharePoint, the opportunity amendment in HubSpot, and the delivery baseline in Kantata. Release stays blocked if any required write fails.</p></div><div class="write-status">${['SharePoint','HubSpot','Kantata'].map(name=>`<span class="${state.writes[name]===state.revision?'complete':''}">${state.writes[name]===state.revision?'✓':'○'} ${name}<small>${state.writes[name]===state.revision?'Saved + verified':'Not verified'}</small></span>`).join('')}</div><label class="fault-control">Test a real-world exception<select id="fault" ${state.ready?'disabled':''}><option value="none" ${state.fault==='none'?'selected':''}>No fault</option><option value="crm" ${state.fault==='crm'?'selected':''}>HubSpot update fails</option><option value="revision" ${state.fault==='revision'?'selected':''}>New client revision before release</option></select></label><button class="primary" data-action="sync" ${allApproved(state)&&!state.ready?'':'disabled'}>${state.ready?'✓ Proposal ready for final send review':'Apply approved updates (simulation) →'}</button>${state.notice?`<p class="notice" role="status">${e(state.notice)}</p>`:''}</section><details class="build-details"><summary>What Nine-67 would build behind this screen</summary><div class="build-grid"><article><b>1. Connect and identify</b><p>Use permitted Microsoft 365, CRM and PM integrations to collect files and match the opportunity and revision. Route ambiguous matches to a person.</p></article><article><b>2. Keep shared requirements</b><p>Persist scope, locations, duration, budget constraints, owners and source versions. Preserve previous versions and link evidence to decisions.</p></article><article><b>3. Analyze dependencies</b><p>AI proposes affected sections and revisions. Explicit checks compare staffing, price, dates, locations and commitments; owners review the interpretation.</p></article><article><b>4. Run the decisions</b><p>A durable workflow tracks approvals, reminders and escalation. Changed sources invalidate affected decisions. AI does not approve its own proposal.</p></article><article><b>5. Update and verify</b><p>Apply approved writes with safe retries and read-back verification. Track partial failures. Do not create duplicate documents or announce completion prematurely.</p></article><article><b>6. Pilot and measure</b><p>Start with one workflow, sample replays and approved writes. Measure coordination effort, elapsed proposal time, approval waiting and rework against the real baseline.</p></article></div></details><details class="audit"><summary>Decision and update history · ${state.audit.length} events</summary><ol>${state.audit.map(row=>`<li><small>#${row.sequence} · revision ${row.revision}</small>${e(row.message)}</li>`).join('')}</ol></details><p class="microcopy">Draft revised fee: ${money(n.fee)}. All amounts, staffing assumptions and approvals are fictional demonstration data.</p>`;
}
function sceneFive(state){
 if(!state.ready)return `<div class="empty-state"><span class="large-symbol">○</span><h2>The proposal is not ready yet.</h2><p>Finish the owner reviews, leadership approval and simulated system verification. Navigating to this page cannot bypass those steps.</p><button class="primary" data-goto="3">Return to the connected workflow →</button></div>`;
 const n=numbers(state);
 return `<div class="ready-banner"><span>✓</span><div><p class="eyebrow">Verified revision ${state.revision}</p><h2>One proposal Leah can stand behind.</h2><p>${e(state.sites.join(' + '))} · ${money(n.fee)} · 90 days · ${n.days} consultant-days</p></div>${badge('Ready for final send review','green')}</div><div class="completion-cards"><article><b>5 owner decisions</b><p>Each contribution approved against the same requirement revision.</p></article><article><b>1 leadership approval</b><p>The complete commercial commitment reviewed as a single packet.</p></article><article><b>3 verified updates</b><p>SharePoint, HubSpot and Kantata agree in this simulation.</p></article></div><details class="final-preview" open><summary>Final executive summary</summary><div class="document-paper"><p class="document-label">SUMMIT ADVISORY GROUP / NORTHSTAR DISTRIBUTION</p><h2>90-day operational improvement proposal</h2><p>${e(artifact(state,'marketing')[2])}</p><p>${e(artifact(state,'marketing')[3])}</p><p><b>Delivery:</b> diagnostic, design and implementation, with the approved parallel staffing model. <b>Terms:</b> locations, fee, client dependencies and written change control aligned to revision ${state.revision}.</p><button data-action="download" class="secondary">Download sample proposal summary (.html)</button></div></details>${mailThread(email('Leah','Sales · Proposal owner → Rachel','Draft · Not sent',`<p>Hi Rachel,</p><p>Our updated proposal covers <b>${e(state.sites.join(' and '))}</b> within the 90-day engagement, with the parallel staffing plan reviewed by delivery.</p><p>The proposed fee is <b>${money(n.fee)}</b>. The scope, staffing, pricing and terms have been reviewed together and are reflected consistently in the proposal.</p><p>We’re ready to walk your team through the complete plan.</p><p>Best,<br>Leah</p>`))}<div class="closing-quote"><p>“We connected their work, their information, and their decisions.”</p><span>That is the difference between faster individual tasks and completed company work.</span></div><section class="assessment"><div><p class="eyebrow">Included for webinar attendees</p><h2>Complimentary workflow assessment.</h2><p>Find your manual handoffs. Identify where AI can help.</p><small>Scheduled separately after the webinar. One workflow map, its decisions and a baseline metric.</small></div><div id="booking-content"><b>Type “assessment” and your workflow in chat.</b><p>Suuchi Ramesh · CEO/FDE<br>Josh Lee · COO/FDE</p></div></section>`;
}
export function renderScene(state){return [sceneOne,sceneTwo,sceneThree,sceneFour,sceneFive][state.scene](state);}
export function renderSidebar(state){
 const n=numbers(state);
 const content=[
 ['Everyone used AI well.','Leah · Sales / proposal owner','Five contributors use ChatGPT, Copilot and Claude to produce correct Austin deliverables.','Done locally','Scope, staffing, price, terms and summary are complete individually.','Still manual','Collecting the files, aligning versions, assembling the packet and obtaining final approval.','Next: a new client requirement arrives.'],
 ['The requirement changes.','Rachel · Client / Leah · Sales','Rachel adds Denver after the original work is finished. Leah acknowledges it accurately.','What changed','Locations and staffing assumptions now need a revised commercial and contractual review.','Why this matters','The old documents were correct. Their assumptions must now move together through five people’s work.','Next: watch Leah do that coordination.'],
 ['Leah does the connecting.','Leah · Sales / proposal owner','She downloads, compares, messages, copies decisions, tracks versions and chases approvals.','AI can help again','Each owner can revise their own contribution faster. They still need current inputs from each other.','The business problem','Five task-level productivity wins leave hours of coordination with one person. The proposal is still waiting.','Illustrative effort only; not measured savings.'],
 ['The workflow carries it.','Named owners + leadership','Shared requirements route the affected work. Approved decisions unlock the dependent reviews.','What Nine-67 builds','Connected records, change impact, version-aware approvals, revised drafts and verified updates.','What people still own','Staffing, price, terms, narrative and final authorization. Missing decisions or failed writes block release.',state.ready?'Current state: ready for Leah’s final review.':`Current state: ${Object.keys(dependencies).filter(id=>approved(state,id)).length} / 6 decisions approved.`],
 [state.ready?'One completed outcome.':'Completion has a gate.','Leah · Final client review',state.ready?'The proposal now represents one aligned set of approved decisions.':'Opening the final page does not approve or update anything.','What counts as ready',state.ready?`${n.days} consultant-days, ${money(n.fee)}, ${state.sites.length} locations, 90 days. All approvals and simulated writes verified.`:'All owner decisions, leadership approval and required system writes must be verified.','The webinar message','Connect the work between people’s AI tools so a customer request becomes completed work.','No customer email is sent by this demo.']
 ][state.scene];
 const relevant=state.scene===0?[owners.find(row=>row.id===state.selectedOwner)]:state.scene===1?[owners[0]]:owners;
 return `<div class="explanation-heading"><small>WHAT’S HAPPENING · ${state.scene+1} / 5</small><h2>${content[0]}</h2></div><div class="explanation-body"><h3>${content[1]}</h3><p>${content[2]}</p><div class="sidebar-tool-list">${relevant.map(owner=>`<div><b>${owner.name} · ${owner.department.split(' · ')[0]}</b>${tools(owner)}</div>`).join('')}</div></div><div class="explanation-done"><small>${content[3]}</small><p>${content[4]}</p></div><div class="explanation-gap ${state.scene>=3?'solution':''}"><small>${content[5]}</small><p>${content[6]}</p></div><p class="sidebar-next">${content[7]}</p><div class="presenter-line"><small>THE POINT TO LAND</small><p>“${scenes[state.scene].cue}”</p></div>`;
}
